-- 店铺保证金本地演示数据补充：退款申请 + 流水 + 退款中/已退账户状态
SET NAMES utf8mb4;
USE qixi_crm_admin;

DELETE FROM qixi_crm_a_merchant_deposit_ledger WHERE id BETWEEN 960001 AND 960200;
DELETE FROM qixi_crm_a_merchant_deposit_refund WHERE id BETWEEN 960001 AND 960200;



UPDATE qixi_crm_a_merchant_deposit_account SET state='refund_pending', updated_at=NOW() WHERE merchant_id IN (1004,1008,1012,1016,1020,1024,1028,1032);
UPDATE qixi_crm_a_merchant_deposit_account SET state='refunded', available_amount=0, updated_at=NOW() WHERE merchant_id IN (1036,1040,1044,1048,1052,1056,1060,1064);

SELECT state, COUNT(*) c FROM qixi_crm_a_merchant_deposit_account GROUP BY state;
SELECT status, COUNT(*) c FROM qixi_crm_a_merchant_deposit_refund GROUP BY status;
SELECT COUNT(*) ledgers FROM qixi_crm_a_merchant_deposit_ledger;
SELECT id, merchant_id, amount, status, reason FROM qixi_crm_a_merchant_deposit_refund WHERE id BETWEEN 960001 AND 960200 ORDER BY id DESC LIMIT 5;